const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const sticks = data.slice(1).sort((a, b) => a - b);

let count = 0;

for (let k = 2; k < n; k++) {
  let i = 0;
  let j = k - 1;

  while (i < j) {
    if (sticks[i] + sticks[j] > sticks[k]) {
      count += j - i;
      j--;
    } else {
      i++;
    }
  }
}

console.log(count);
